// CSD_RATIONALE_BEGIN
// Root-cause of 0.0% (attempt 63) vs 40.8% (best):
// The guidance in attempt 63 said "SHORTEST correct arithmetic expression" and
// "Stop as soon as the expression is complete", which directly instructed the model
// to close spans after a single token (e.g., <<n0>>, <<r>>, <<d>>). Combined with
// CloseSpanIfComplete closing at the very first IsCompletePrefix, this produced
// 22.9 spans/example averaging 1.14 tokens each. The last span was always a single
// variable/constant, giving 0% accuracy.
//
// Fix 1: Restore guidance similar to the best attempt (with a multi-token example),
// and explicitly tell the model that each span should contain a COMPLETE multi-token
// expression, not a single variable.
//
// Fix 2: Add a minimum token count before closing: only close when
// parser.IsCompletePrefix(currentConstrainedOut) AND |currentConstrainedOut| > 1.
// This prevents single-variable closures. The model continues inside the span and
// generates a full binary/compound expression (e.g., n0 + n1) before we close.
// For the rare case where the correct answer IS a single token, CloseSpanWithinBudget
// at budget pressure handles the forced close.
//
// Fix 3: Use RenderedEndsWith(generated, "<<") for robust delimiter detection
// (handles both split and single-token "<<").
//
// Fix 4: Keep the best attempt's force-open at budget pressure (<= 4 steps) to
// ensure a final constrained span is always emitted.
//
// Flow:
// Phase 1 (outside span): UnconstrainedStep; on RenderedEndsWith("<<") call
//   EnterObservedConstrainedSpan (cost 0, no duplicate delimiter).
// Phase 2 (inside span): if complete AND |current| > 1, CloseConstrainedSpan.
//   Near budget (<=3 steps), CloseSpanWithinBudget forces close.
//   Otherwise AdaptiveConstrainedStep + AppendConstrainedToken.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch: insideConstrainedOut is false so the implication is
//   vacuous. When RenderedEndsWith fires, EnterObservedConstrainedSpan sets
//   insideConstrainedOut := true and currentConstrainedOut := []; the precondition
//   parser.IsValidPrefix([]) holds by method precondition.
//
//   OpenConstrainedSpan branch (force-open at budget pressure): sets
//   insideConstrainedOut := true, currentConstrainedOut := []; parser.IsValidPrefix([]) ✓.
//
//   CloseConstrainedSpan branch: sets insideConstrainedOut := false, making the
//   implication vacuously true; currentConstrainedOut := [].
//
//   CloseSpanWithinBudget branch: its postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
//   AdaptiveConstrainedStep + AppendConstrainedToken: AdaptiveConstrainedStep
//   returns a token valid at currentConstrainedOut (hard-masked); AppendConstrainedToken
//   extends currentConstrainedOut by that token, preserving parser.IsValidPrefix by
//   IsTokenValidNext. EOS path breaks without appending, so the invariant holds vacuously
//   on exit.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Initialization: equality holds (generated = generatedPrefix, steps = 0). ✓
//
//   Outside-span, UnconstrainedStep: steps += 1; generated grows by at most 1
//   (EOS breaks without appending). EnterObservedConstrainedSpan leaves generated
//   unchanged. Invariant preserved. ✓
//
//   OpenConstrainedSpan: appends "<<" (+1 token), steps += 1. Invariant preserved. ✓
//
//   CloseConstrainedSpan: appends ">>" (+1 token), steps += 1. Invariant preserved. ✓
//
//   CloseSpanWithinBudget with closeBudget = maxSteps - steps: helper postcondition
//   gives |generated_new| <= |generated_old| + closeBudget = |generated_old| + (maxSteps - steps).
//   After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken: AppendConstrainedToken appends
//   exactly 1 token; steps += 1. Invariant preserved. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap every intermediate symbolic expression and the final numeric answer inside << >> delimiters.\n" +
  "Each << >> span must contain a COMPLETE arithmetic expression with at least one operator—not a single variable or constant alone.\n" +
  "Example: The total cost is <<n * price + tax>>. The percentage is <<100 * hits // total>>.\n" +
  "Use // for integer division. Do not use ** for exponentiation.\n" +
  "The LAST << >> span must contain the complete final answer as one arithmetic expression.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Force-open a final constrained span at budget pressure.
    if maxSteps - steps <= 4 && steps > 0 {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // Use RenderedEndsWith for robust delimiter detection (handles split tokens).
        if RenderedEndsWith(generated, "<<") {
          var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := og;
          insideConstrainedOut := oi;
          currentConstrainedOut := oc;
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| > 1 {
      // Span is complete AND has at least 2 tokens (prevents single-variable closures).
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Near budget: force close whatever we have.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Continue generating constrained tokens inside the span.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

